# Lesson 2, parts 2, 3 and 4.
# ================================================================ part 3
opener(2, 'השחקנים', 'שאלת החלק: למה כל צד נכנס לעסקה?',
       ['מגדר (Hedger): דנה נועלת שער, צעד אחר צעד', 'ספקולנט (Speculator): מנוף (Leverage) בחוזה ובאופציה', 'זיהוי התפקיד, והסכנה במעבר בין תפקידים'], 20, note='<b>במפגש 1:</b> שלושה מניעים להיכנס לחוזה, ודנה שחשופה לדולר. <b>היום:</b> מגדר וספקולנט עם מספרים מלאים. דנה נועלת שער, ויואב מקבל מנוף.')

_t, _n = GT(['השער בעוד 3 חודשים ($S_{T}$)', 'התשלום לספק (ש״ח)', 'הערך שנובע מחוזה האקדמה (ש״ח)', 'העלות נטו לדנה (ש״ח)'], [
    ['3.20', ('1,600,000', '$500,000 × 3.20$'), ('$-175,000$', '$500,000 × (3.20 − 3.55)$'), ('1,775,000', '$1,600,000 + 175,000$')],
    ['3.55', ('1,775,000', '$500,000 × 3.55$'), ('0', '$500,000 × (3.55 − 3.55)$'), ('1,775,000', '$1,775,000 − 0$')],
    ['3.90', ('1,950,000', '$500,000 × 3.90$'), ('175,000', '$500,000 × (3.90 − 3.55)$'), ('1,775,000', '$1,950,000 − 175,000$')]], 1)
S('s-hedger0', 'מגדר: הגדרה', 'מגדר (Hedger): מי זה',
  '<div class="row eq2 top">'
  + DEF('מגדר (Hedger)', 'מי שמקטין סיכון שכבר קיים בעסק שלו. הסיכון קיים בלי קשר לחוזה, והחוזה רק מקטין אותו.', 'דנה, יבואנית הרהיטים, תשלם לספק 500,000 דולר. אם הדולר יעלה, הרהיטים יעלו לה יותר. חוזה אקדמה על הדולר מקבע לה את העלות בשקלים.', trm='hedger')
  + ST(1, '<div class="card"><b class="ct">מה המגדר קונה</b><p class="lg">' + TX('ודאות: הוא יודע היום כמה ישלם, בכל שער.') + '</p><p class="lg">' + TX('לא רווח: אם השער ינוע לטובתו, הוא לא ייהנה מכך.') + '</p></div>') + '</div>'
  + TOON('sweat', 'לפני הגידור: בודקים את השער כל בוקר. אחרי: בודקים את הרהיטים.', 2), kick=f'חלק {CUR[0]} · הגדרה והדגמה')

S('s-hedger', 'מגדר: דנה נועלת שער', 'מגדר (Hedger): דנה קונה חוזה אקדמה (Forward)',
  '<div class="card qstem"><p>' + TX('דנה, יבואנית הרהיטים, צריכה להיערך לתשלום של 500,000 דולר לספק בעוד שלושה חודשים. כדי להבטיח שתוכל לשלם בלי להיות חשופה לשער הדולר, היא מתקשרת כבר היום בחוזה אקדמה (Forward) לקניית דולרים (Long), על סכום של 500,000 דולר, במחיר חוזה (K) של 3.55 ש״ח לדולר.') + '</p><p>' + TX('<b>נדרש:</b> לכל שער אפשרי בעוד שלושה חודשים, 3.20, 3.55 או 3.90, הציגו את התשלום לספק בשקלים לפי השער באותו יום, את הערך שנובע מחוזה האקדמה, ואת העלות נטו של העסקה לדנה.') + '</p></div>'
  + _t
  + ST(_n, '<div class="card fmline"><b class="ct">איך מחשבים כל עמודה</b> ' + TX('<b>תשלום לספק</b> = 500,000 × השער באותו יום. <b>ערך החוזה</b> = 500,000 × (השער − 3.55): דנה קונה ב-3.55 דולרים ששווים בשוק את השער. <b>עלות נטו</b> = התשלום לספק − ערך החוזה.') + '</div>')
  + BAND('dg', 'בכל שער העלות נטו 1,775,000 ש״ח: ודאות, לא רווח.', _n + 1), kick=f'חלק {CUR[0]} · בנייה בהדרגה')

_d = {'A1': 'תשלום (דולר)', 'B1': 500000, 'A2': 'מחיר החוזה (K)', 'B2': 3.55, 'A4': 'שער בפקיעה', 'B4': 'תשלום לספק', 'C4': 'תוצאת החוזה', 'D4': 'עלות נטו'}
_s = {}
for i, p in enumerate([3.2, 3.4, 3.55, 3.7, 3.9]):
    r = 5 + i; _d[f'A{r}'] = p; _s[f'B{r}'] = f'=$B$1*A{r}'; _s[f'C{r}'] = f'=$B$1*(A{r}-$B$2)'; _s[f'D{r}'] = f'=B{r}-C{r}'
XLS('x-hedge', 'אקסל: גידור של דנה', 'אקסל: הגידור של דנה (Hedging)',
    'דנה, יבואנית הרהיטים, תשלם לספק 500,000 דולר בעוד שלושה חודשים. כדי לדעת כבר היום כמה שקלים תשלם, היא קונה (Long) חוזה אקדמה (Forward) על 500,000 דולר, במחיר חוזה (K) של 3.55 ש״ח לדולר. הציגו בטבלה את התשלום לספק בשקלים, את תוצאת החוזה ואת העלות נטו, כשהשער בפקיעה נע בין 3.20 ל-3.90. מה מיוחד בעמודה D?', _d, _s, [160, 130, 130, 130], [4],
    hints=['תשלום לספק: דולרים × שער בפקיעה.', 'תוצאת החוזה ל-Long: דולרים × (שער בפקיעה − K).', 'עלות נטו: תשלום לספק פחות תוצאת החוזה.'], remind='<b>תשלום לספק</b> = כמות × שער בפקיעה.<br><b>תוצאת Long</b> = כמות × ($S_{T} − K$).<br><b>עלות נטו</b> = תשלום לספק − תוצאת החוזה.', partial=['B5', 'C5', 'D5'], done='עמודה D קבועה: זה הגידור.')

_t, _n = GT(['יום', 'מה קרה במדד', 'רווח או הפסד (ש״ח)', 'יתרה בחשבון (ש״ח)'], [
    ['<b>יום 0</b>', 'קנייה, מדד 4,000', ('הפקדה', '10% מ-200,000'), ('20,000', 'ביטחונות התחלתיים')],
    ['<b>יום 1</b>', ('עלה ל-4,080', '$+2%$, כלומר 80 נקודות'), ('$+4,000$', '$80 × 50$'), ('24,000', '$20,000 + 4,000$')],
    ['<b>יום 2</b>', ('ירד ל-3,876', '$−5%$, כלומר 204 נקודות'), ('$-10,200$', '$−204 × 50$'), ('13,800', '$24,000 − 10,200$')],
    ['<b>קריאה להשלמה</b>', 'היתרה מתחת ל-15,000', ('משלימים 6,200', '$20,000 − 13,800$'), ('20,000', 'חזרה לביטחונות ההתחלתיים')]], 4)
S('s-margin', 'ביטחונות: איך זה עובד', 'ביטחונות (Margin): איך מחשבים אותם, ומה הרעיון',
  '<div class="row eq2 top"><div class="rl">'
  + RL(['<b>הבעיה.</b> בחוזה עתידי (Futures) לא משלמים מחיר היום, אבל שני הצדדים מחויבים. מי מבטיח שהצד המפסיד ישלם?',
        '<b>הפתרון.</b> המסלקה (Clearing house) דורשת מכל צד להפקיד <b>ביטחונות (Margin)</b>: כסף בחשבון, שממנו יורדים ההפסדים.',
        '<b>כמה מפקידים?</b> אחוז מהחשיפה, שהבורסה והמסלקה קובעות. בדוגמה, להמחשה: 10%. חשיפה של 200,000 ש״ח דורשת ביטחונות של $200,000 × 10% = 20,000$ ש״ח.']) + '</div><div class="col">'
  + _t + ST(_n, '<div class="card fmline"><b class="ct">בכל יום</b> ' + TX('הרווח נוסף לחשבון וההפסד יורד ממנו. אם היתרה יורדת מתחת ל<b>ביטחונות שמירה (Maintenance margin)</b>, כאן 15,000 ש״ח, מקבלים <b>קריאה להשלמת ביטחונות (Margin call)</b> ומשלימים חזרה ל-20,000. מי שלא משלים, הפוזיציה שלו נסגרת. נרחיב בשיעור 3.') + '</div>') + '</div></div>', kick=f'חלק {CUR[0]} · הגדרה בהדרגה')

Q('s-spec', 'שאלה', 'ספקולנט (Speculator): חשיפה גדולה, הון קטן',
  ['יואב, סטודנט, אינו יבואן ואין לו שום עסק שקשור למדד. הוא מעריך שמדד המניות יעלה, ולכן קונה (Long) חוזה עתידי (Futures) אחד על המדד.',
   '<b>הנתונים:</b> המדד עומד היום על 4,000 נקודות ($I$). כל נקודה במדד שווה 50 ש״ח: זה המכפיל ($m$). המסלקה דורשת ביטחונות (Margin) של 10% מהחשיפה. למחרת המדד עולה ב-2%.',
   '<b>נדרש:</b> החשיפה בשקלים, הביטחונות, המנוף, הרווח בשקלים והתשואה על הביטחונות.'],
  ['<b>1. חשיפה (E):</b> נקודות × מכפיל.', '=E = I × m = 4,000 × 50 = 200,000',
   '<b>2. ביטחונות:</b> 10% מהחשיפה. זה ההון של יואב.', '=Margin = 10% × E = 20,000',
   '<b>3. מנוף (L):</b> פי כמה החשיפה גדולה מההון.', '=L = \\f{E}{Margin} = \\f{200,000}{20,000} = 10',
   '<b>4. רווח (P&L):</b> 2% מ-4,000 הם 80 נקודות.', '=P&L = 80 × 50 = 4,000',
   '<b>5. תשואה על הביטחונות (R):</b>', '=R = \\f{P&L}{Margin} = \\f{4,000}{20,000} = 20%'],
  'חשיפה 200,000 ש״ח, ביטחונות 20,000, מנוף 10, רווח 4,000 ותשואה 20%. קיצור דרך: מנוף × שינוי במדד.',
  extra=MORE('📖 לחצו כאן להסבר המלא: ספקולנט, מנוף וביטחונות',
             '<p>' + TX('<b>ספקולנט (Speculator):</b> מי שנוטל סיכון, בלי חשיפה קיימת, כדי להרוויח משינוי מחיר. ליואב אין חשיפה למדד לפני העסקה.') + '</p>'
             '<p>' + TX('<b>מנוף (Leverage):</b> חשיפה גדולה תמורת הון קטן. במנוף 10, כל שינוי במדד מוכפל פי 10 בתשואה על ההון, ברווח וגם בהפסד.') + '</p>'
             '<p>' + TX('<b>ביטחונות (Margin):</b> כסף שמפקידים כדי להבטיח שהצד יעמוד בחוזה. ההפסדים יורדים מהחשבון הזה: ירידה של 2% מורידה ממנו 4,000 ש״ח.') + '</p>'))

_d = {'A1': 'רמת המדד', 'B1': 4000, 'A2': 'מכפיל (ש״ח)', 'B2': 50, 'A3': 'ביטחונות (ש״ח)', 'B3': 20000, 'A4': 'חשיפה (ש״ח)', 'A5': 'מנוף', 'A7': 'שינוי במדד', 'B7': 'רווח או הפסד', 'C7': 'תשואה על ההון'}
_s = {'B4': '=B1*B2', 'B5': '=B4/B3'}
for i, p in enumerate(['-10%', '-2%', '2%', '5%']):
    r = 8 + i; _d[f'A{r}'] = p; _s[f'B{r}'] = f'=$B$4*A{r}'; _s[f'C{r}'] = f'=B{r}/$B$3'
XLS('x-lev', 'אקסל: מנוף', 'אקסל: המנוף (Leverage) של יואב',
    'יואב, סטודנט שאין לו שום עסק שקשור למדד, מעריך שמדד המניות יעלה. הוא קונה (Long) חוזה עתידי (Futures) אחד על המדד, שעומד היום על 4,000 נקודות. המדד נמדד בנקודות, ובחוזה הזה כל נקודה במדד שווה 50 ש״ח: זה המכפיל (Multiplier). הוא מפקיד ביטחונות (Margin) של 20,000 ש״ח. חשבו את החשיפה בשקלים ואת המנוף (Leverage). אחר כך הציגו את הרווח או ההפסד ואת התשואה על הביטחונות, אם המדד יורד ב-10% או ב-2%, או עולה ב-2% או ב-5%. מה קורה להון של יואב בירידה של 10%?', _d, _s, [170, 140, 150], [7],
    hints=['חשיפה בשקלים: רמת המדד בנקודות כפול המכפיל, כלומר כפול השקלים שכל נקודה שווה.', 'מנוף: חשיפה ÷ ביטחונות.', 'רווח: חשיפה × שינוי במדד.'], remind='<b>חשיפה (ש״ח)</b> = רמת המדד בנקודות × מכפיל (ש״ח לכל נקודה).<br><b>מנוף</b> = חשיפה ÷ ביטחונות.<br><b>רווח או הפסד</b> = חשיפה × שינוי במדד.<br><b>תשואה על ההון</b> = רווח ÷ ביטחונות.', partial=['B4', 'B5'], done='בירידה של 10% ההון נמחק כולו. זה הצד השני של המנוף.')

_t, _n = GT(['המחיר בפקיעה ($S_{T}$)', '40 מניות: רווח (ש״ח)', '40 מניות: תשואה', '1,000 אופציות: רווח (ש״ח)', '1,000 אופציות: תשואה'], [
    ['120', ('800', '$40 × (120 − 100)$'), ('20%', '$800 ÷ 4,000$'), ('11,000', '$1,000 × (15 − 4)$'), ('275%', '$11,000 ÷ 4,000$')],
    ['105', ('200', '$40 × (105 − 100)$'), ('5%', '$200 ÷ 4,000$'), ('$-4,000$', '$1,000 × (0 − 4)$'), ('$-100%$', '$−4,000 ÷ 4,000$')],
    ['95', ('$-200$', '$40 × (95 − 100)$'), ('$-5%$', '$−200 ÷ 4,000$'), ('$-4,000$', '$1,000 × (0 − 4)$'), ('$-100%$', '$−4,000 ÷ 4,000$')]], 1)
S('s-specopt', 'מנוף באופציה', 'מנוף באופציה: 4,000 ש״ח בשתי דרכים',
  '<div class="card qstem"><p>' + TX('מניה נסחרת היום ב-100 ש״ח. אופציית רכש (Call) עליה, במחיר מימוש (K) של 105 ש״ח, עולה פרמיה (c) של 4 ש״ח, במכפיל 1. לספקולנט יש 4,000 ש״ח, והוא מעריך שהמניה תעלה. הוא יכול לקנות בהם 40 מניות, או 1,000 אופציות. מה הרווח והתשואה בכל דרך, בשלושה מחירים בפקיעה? המחירים להמחשה.') + '</p></div>' + _t
  + BAND('trap', 'במחיר 105 המניה עלתה, והמחזיק במניות הרוויח. בעל האופציות הפסיד הכול. באופציה לא די לצדוק בכיוון: צריך לעבור את נקודת האיזון (Break-even), 109.', _n)
  + ST(_n + 1, MORE('📖 לחצו כאן: מאיפה הגיעו 15 − 4 ו-0 − 4?',
       '<p>' + TX('<b>40 מניות:</b> קנינו כל מניה ב-100. במחיר 120 כל מניה הרוויחה $120 − 100 = 20$, ועל 40 מניות $40 × 20 = 800$.') + '</p>'
       '<p>' + TX('<b>1,000 אופציות, במחיר 120:</b> כל אופציה נותנת זכות לקנות ב-105 מניה ששווה 120. התזרים בפקיעה (Payoff) לאופציה: $120 − 105 = 15$. שילמנו עליה פרמיה (c) של 4, ולכן הרווח לאופציה $15 − 4 = 11$, ועל 1,000 אופציות $11,000$.') + '</p>'
       '<p>' + TX('<b>במחיר 105 או 95:</b> לקנות ב-105 מניה ששווה 105 או פחות אין טעם, ולכן לא מממשים. התזרים 0, והפרמיה כבר שולמה: $0 − 4 = −4$ לאופציה, ועל 1,000 אופציות $−4,000$, כל הכסף.') + '</p>')), kick=f'חלק {CUR[0]} · בנייה בהדרגה')

SORTER('a-who', 'פעילות: מי השחקן', 'מי השחקן?',
       'לכל מצב: מגדר (Hedger) או ספקולנט (Speculator)?',
       ['מגדר (Hedger)', 'ספקולנט (Speculator)'], [
           ('קבלן שמשלם לספקים באירו, והכנסותיו בשקלים, קונה חוזים על האירו', 0, 'יש לו חשיפה עסקית, והחוזה מקטין אותה.'),
           ('קרן שצופה עלייה בניקל, וקונה חוזים בלי צורך בניקל', 1, 'אין לה חשיפה קיימת. היא נוטלת סיכון מתוך ציפייה.'),
           ('קרן פנסיה שקונה Put על מדד כדי להגן על תיק המניות', 0, 'התיק קיים, וה-Put מגביל את ההפסד.'),
           ('סטודנט שקונה Call על מניה, לפני פרסום דוחות', 1, 'אין לו חשיפה למניה. הוא מהמר על כיוון המחיר.'),
           ('חקלאי שמוכר חוזה על חיטה לפני הקציר', 0, 'החוזה מגן על הכנסה מיבול שכבר בשדה.')])

S('s-danger', 'הסכנה: מעבר בין תפקידים', 'המכשיר אינו קובע את התפקיד',
  '<div class="row eq2 top"><div class="card"><b class="ct">אותו חוזה, שני תפקידים</b><p class="lg">' + TX('Long בחוזה אקדמה (Forward) על דולר הוא גידור (Hedging) בידי יבואן. בידי מי שאין לו תשלום בדולרים, אותו חוזה הוא ספקולציה (Speculation).') + '</p><p class="lg">' + TX('המבחן: האם הפוזיציה מקטינה חשיפה קיימת, או יוצרת חשיפה חדשה?') + '</p></div>'
  + ST(1, '<div class="card"><b class="ct">איך זה משתבש</b><p class="lg">' + TX('סוחר מקבל מנדט לגדר, ועובר לפוזיציות כיווניות בלי ידיעת הארגון. בנק Barings קרס כך ב-1995. נעסוק בכך בשיעור 12.') + '</p></div>') + '</div>'
  + ST(2, '<div class="card" style="margin-top:12px"><b class="ct">הבקרה הבסיסית</b><ul class="lg"><li>' + TX('תקרה לכל סוחר, שקובע מי שאינו הסוחר.') + '</li><li>' + TX('התאמה בין היקף הנגזרים לחשיפה העסקית, בכל דוח.') + '</li></ul></div>'), kick=f'חלק {CUR[0]} · סיכום')

